    `${b('GOLD STATE:')} ${state.gold ? `${esc(state.gold.value)} (24h ${esc(fmtPct(state.gold.change_24h_pct))}, 5d ${esc(fmtPct(state.gold.change_5d_pct))})${L.gold ? ` · ${esc(L.gold.state)}` : ''}` : 'unavailable'}`,
