}

function parseCommand(text) {
  const t = String(text || '').trim();
  if (!t.startsWith('/')) return null;
  const [head, ...rest] = t.split(/\s+/);
  const cmd = head.split('@')[0].toLowerCase();
  return { command: cmd, args: rest, known: COMMANDS.includes(cmd) };
}

