      alerts.push({ kind: 'FALLBACK', trigger: `primary ${m.status}`, model: m.model, display_name: m.display_name, reason: m.reason, lastFailure: lf || null });
      st.last_fallback_alert_at = nowIso;
    }
    ms.status = m.status;
    st.models[m.model] = ms;
